};

export type CapabilityContract<Value, Token extends string> = {
    readonly value: Value;
    readonly compatibility: {
        readonly family: "exact";
        readonly familyVersion: 1;
        readonly token: Token;
    };
};

export type CapabilitySchema<C> = {
    readonly [K in keyof C]: CapabilityContract<unknown, string>;
};

export type CreatedEntry = {
    readonly moduleId: string;
    readonly implementationId: string;
    readonly instance: unknown;
    readonly capabilities: Readonly<Record<string, unknown>>;
};

export type FactoryCapabilities<C, D extends ModuleDeclaration> = {
