    } ? V : never : never) | undefined : (S["capabilityId"] extends keyof C ? C[S["capabilityId"]] extends {
        readonly value: infer V;
    } ? V : never : never);
};

export type FactoryHandle<C, D extends ModuleDeclaration = ModuleDeclaration, I = unknown> = {
    readonly [scope]: (capabilities: C) => C;
    readonly [detail]: {
        readonly declaration: D;
        readonly instance: I;
    };
};

export type FactoryProduct<I, P> = {
    readonly instance: I;
    readonly capabilities: P;
};

export type ObservedCancellation = {
    readonly reason: unknown;
};

export type PreparedAssembly<R> = {
    readonly run: (options?: RunOptions) => Promise<AssemblyOutcome<R>>;
};

export type ReturnedProduct = {
    readonly implementationId: string;
    readonly product: unknown;
};

export type RootInstances<R> = {
    readonly [K in keyof R]: R[K] extends FactoryHandle<infer _C, infer _D, infer I> ? I : never;
};

export type RunOptions = {
    readonly signal?: AbortSignal;
};

export type SuccessfulComposition = Extract<CompileCompositionResult, {
    readonly plan: CompositionPlan;
    readonly digest: PlanDigest;
}>;
